  addTwoNumbers(l1, l2) {
    const dummy = new ListNode(0);
    let tail = dummy;
    let carry = 0;
    while (l1 !== null || l2 !== null || carry > 0) {
      const sum = (l1 ? l1.val : 0) + (l2 ? l2.val : 0) + carry;
