class Solution {
  convert(s, numRows) {
    if (numRows === 1) return s;
    const rows = new Array(Math.min(numRows, s.length)).fill("");
    let current = 0;
    let goingDown = false;
    for (const char of s) {
      rows[current] += char;
      if (current === 0 || current === numRows - 1) goingDown = !goingDown;
      current += goingDown ? 1 : -1;
    }
    return rows.join("");
  }
}

