class Solution {
  reverseKGroup(head, k) {
    const dummy = new ListNode(0, head);
    let groupPrev = dummy;

    while (true) {
      let kth = groupPrev;
      for (let i = 0; i < k; i++) {
        kth = kth.next;
        if (kth === null) return dummy.next;
      }
      let groupNext = kth.next;
      let prev = groupNext;
      let curr = groupPrev.next;
      for (let i = 0; i < k; i++) {
        const next = curr.next;
        curr.next = prev;
        prev = curr;
        curr = next;
      }
      const tmp = groupPrev.next;
      groupPrev.next = kth;
      groupPrev = tmp;
    }
  }
}

