class Solution {
  totalNQueens(n) {
    let count = 0;
    const board = new Array(n).fill(-1);

    const isValid = (row, col) => {
      for (let r = 0; r < row; r++) {
        const c = board[r];
        if (c === col || Math.abs(r - row) === Math.abs(c - col)) return false;
      }
      return true;
    };

    const backtrack = (row) => {
      if (row === n) {
        count++;
        return;
      }
      for (let col = 0; col < n; col++) {
        if (isValid(row, col)) {
          board[row] = col;
          backtrack(row + 1);
          board[row] = -1;
        }
      }
    };

    backtrack(0);
    return count;
  }
}

