class Solution {
  sortList(head) {
    if (head === null || head.next === null) return head;
    let slow = head;
    let fast = head.next;
    while (fast !== null && fast.next !== null) {
      slow = slow.next;
      fast = fast.next.next;
    }
    const mid = slow.next;
    slow.next = null;
    const left = this.sortList(head);
    const right = this.sortList(mid);
    return this.merge(left, right);
  }

  merge(l1, l2) {
    const dummy = new ListNode(0);
    let tail = dummy;
    while (l1 !== null && l2 !== null) {
      if (l1.val <= l2.val) {
        tail.next = l1;
        l1 = l1.next;
      } else {
        tail.next = l2;
        l2 = l2.next;
      }
      tail = tail.next;
    }
    tail.next = l1 !== null ? l1 : l2;
    return dummy.next;
  }
}

