class Solution {
  findWords(board, words) {
    const result = [];
    const trie = {};
    for (const word of words) {
      let node = trie;
      for (const ch of word) {
        if (!node[ch]) node[ch] = {};
        node = node[ch];
      }
      node.word = word;
    }

    const dfs = (r, c, node) => {
      if (r < 0 || r >= board.length || c < 0 || c >= board[0].length) return;
      const ch = board[r][c];
      if (ch === "#" || !node[ch]) return;
      const child = node[ch];
      if (child.word) {
        result.push(child.word);
        delete child.word;
      }
      board[r][c] = "#";
      dfs(r + 1, c, child);
      dfs(r - 1, c, child);
      dfs(r, c + 1, child);
      dfs(r, c - 1, child);
      board[r][c] = ch;
    };

    for (let r = 0; r < board.length; r++) {
      for (let c = 0; c < board[0].length; c++) {
        dfs(r, c, trie);
      }
    }
    return result;
  }
}

